list_threads.jq_output:
if type != "object" then { error: . } else
{
  chats: [ (.chats // [])[] | {
      threadId: .id,
      title: (.title // .lastMessage.imDisplayName // null),
      type: (.threadType // .chatType),
      oneOnOne: .isOneOnOne,
      external: .isExternal,
      memberCount: ((.members // []) | length),
      members: [ (.members // [])[] | .mri ]
    } ],
  channels: [ (.channels // [])[] | {
      threadId: .id,
      displayName: .displayName,
      team: .parentTeamId,
      memberCount: ((.membershipSummary // {}) | if type=="object" then .totalMemberCount else null end)
    } ],
  teams: [ (.teams // [])[] | {
      teamId: .id,
      displayName: .displayName,
      channels: [ (.channels // [])[] | { threadId: .id, displayName: .displayName } ]
    } ]
}
end

list_updates.jq_output:
if type != "object" then { error: . } else
{
  counts: {
    unreadChats:    ([(.chats // [])[]    | select(.isRead==false and (.hidden|not))] | length),
    unreadChannels: ([(.channels // [])[] | select(.isMessageRead==false and (.isMuted|not))] | length),
    chatsInWindow:  ((.chats // [])|length),
    channelsInWindow:((.channels // [])|length)
  },
  syncToken: ((.metadata // {}) | if type=="object" then (.syncToken // null) else null end),
  unreadChats: [
    (.chats // [])[] | select(.isRead==false and (.hidden|not))
    | { title: (.title // .lastMessage.imDisplayName // "(1:1)"),
        from: (.lastMessage.imDisplayName // .lastMessage.from),
        time: (.lastMessage.originalArrivalTime // .lastMessage.composeTime),
        oneOnOne: .isOneOnOne, external: .isExternal, important: .isHighImportance,
        fromMe: .isLastMessageFromMe,
        preview: ((.lastMessage.content // "") | gsub("<[^>]*>";" ") | gsub("&nbsp;";" ") | gsub("\\s+";" ") | .[0:160]),
        threadId: .id }
  ] | map(select(.fromMe|not)) | sort_by(.time) | reverse,
  unreadChannels: [
    (.channels // [])[] | select(.isMessageRead==false and (.isMuted|not))
    | { channel: .displayName, team: .parentTeamId,
        from: (.lastMessage.imDisplayName // .lastMessage.from),
        time: (.lastMessage.originalArrivalTime // .lastMessage.composeTime),
        important: (.isImportantMessageRead==false),
        preview: ((.lastMessage.content // "") | gsub("<[^>]*>";" ") | gsub("&nbsp;";" ") | gsub("\\s+";" ") | .[0:160]),
        threadId: .id }
  ] | sort_by(.time) | reverse
}
end

send_message.jq_output:
if type != "object" then { error: . }
elif (.OriginalArrivalTime | type) != "number" then { error: . }
else { id: (.OriginalArrivalTime | tostring),
        at: ((.OriginalArrivalTime / 1000 | floor | todate | sub("Z$"; "")) + "." + ((.OriginalArrivalTime % 1000 + 1000) | tostring | .[1:]) + "Z") }
end

user_fetch.jq_output:
if type != "object" then { error: . }
elif (.value | type) != "array" then { error: . }
else [ .value[] | {
    mri, objectId,
    name: .displayName,
    email: (.email // .mail),
    upn: .userPrincipalName,
    jobTitle, department, companyName,
    location: .userLocation,
    userType,
    shortProfile: .isShortProfile
  } ]
end
